head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");

//#include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.gExplDisclsAcptNo;
scwin.gExplDisclsOrdNo;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF30221.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_resizeToWin = function() {
    frame.Width = 920;
    frame.Height = 620;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !정보--;
셋팅-- > function() {
    scwin.gExplDisclsAcptNo = $c.frame.path("../").scwin.gExplDisclsAcptNo;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    $c.stf.setObjectValue(txb_acpt_no, scwin.gExplDisclsAcptNo);
    $c.stf.setObjectValue(txb_isur_cd, scwin.gIsurCd);



    //alert(gExplDisclsAcptNo);

} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/ExplanationDisclosure.do?method=readExplanationDsclReDscl" + "&inputMessageId=EXPLDISCLSRELIST_INOUT" + "&outputMessageId=EXPLDISCLSRELIST_INOUT" + "&EXPLDISCLS_ACPT_NO=" + $c.stf.getObjectValue(txb_acpt_no) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_explrediscls_info.DataID = encodeURI(url);
    dts_explrediscls_info.reset();
} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/ExplanationDisclosure.do?method=listExplanationDsclReDscl&inputMessageId=EXPLDISCLSRELIST_INOUT" + "&outputMessageId=EXPLDISCLSRELIST_INOUT" + "&EXPLDISCLS_ACPT_NO=" + $c.stf.getObjectValue(txb_acpt_no) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_explrediscls_list.DataID = encodeURI(url);
    dts_explrediscls_list.reset();
};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gExplDisclsAcptNo = dts_explrediscls_list.getCellData(eval(obj), "EXPLDISCLS_ACPT_NO");
    scwin.gExplDisclsOrdNo = dts_explrediscls_list.getCellData(eval(obj), "EXPLDISCLS_ORD_NO");
    scwin.gIsurCd = dts_explrediscls_list.getCellData(eval(obj), "ISUR_CD");
};
scwin.fn_OpenDisclViewerMIS = async function(pAcptNo, pViewerStat) {
    var url = "/dsclproc/ULDSTF10001.gfm?" + "gAcptNo=" + pAcptNo + "&gViewerStat=" + pViewerStat + "&frameID=" + frame.FrameID + "&gAccssAuthTpCd=01" + "&gAskScrenID=" + scwin.vScrenID;
    var winTitle = "공시뷰어";
    await $c.frame.CreateDialogFrame("viewer" + pAcptNo, url, winTitle, -50, -50, 1000, 800, "window”");
};
scwin.fn_reload = function() {
    fn_Search();
    $c.frame.path("../").fn_Search();
};
scwin.dts_explrediscls_info_OnLoadError = function() {
    $c.stf.alert_error(dts_explrediscls_info);
};
scwin.dts_explrediscls_list_OnLoadError = function() {
    $c.stf.alert_error(dts_explrediscls_list);
};
scwin.btn_Close_onclick = async function() {
    //self.close();
    await $c.frame.CloseFrame();
};
scwin.grd_explrediscls_list_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "REDISCLS_DISCLS_TITLE") {
        scwin.fn_OpenDisclViewerMIS(scwin.gExplDisclsAcptNo, 'R');
    } else if (colid == "DISCLS_PUBL_DDTM") {
        var url = "/dsclmgt/ULDSTF30222.gfm";
        var winTitle = "해명공시 재공시 상세";
        //frame.CreateFrame("EXPLDISCLS_ACPT_NO"+gExplDisclsAcptNo, url , winTitle ,100, 10, 560, 290, "window" , 0, 0, true);	
        await $c.frame.CreateDialogFrame("EXPL_LIST", "/dsclmgt/ULDSTF30222.gfm", "해명공시 재공시 상세", 300, 100, 700, 500, "window");
    }
};
scwin.btn_New_onclick = async function() {
    var url = "/dsclmgt/ULDSTF30223.gfm";
    var winTitle = "해명공시 신규 등록";
    //frame.CreateFrame("EXPLDISCLS_ACPT_NO"+gExplDisclsAcptNo, url , winTitle ,50, 30, 800, 500+30, "window" , 0, 0, true);	
    await $c.frame.CreateDialogFrame("EXPL_LIST", "/dsclmgt/ULDSTF30223.gfm", "해명공시 신규 등록", 100, 200, 700, 500, "window");
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_resizeToWin();
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_explrediscls_list.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=EXPLDISCLSRELIST_INOUT";
    dts_explrediscls_list.reset();

    //  정보 읽어오기
    fn_ReadInfo();
    fn_Search();
    $c.stf.showObj(txb_acpt_no, false);
    $c.stf.showObj(txb_isur_cd, false);
};
